/* RZ CREW — Xbox One / Gamepad Viewer. Corrected layout, 750 × 630 canvas. */
.controller.xbox, .controller.custom {
  width:750px!important;height:630px!important;
  background-image:url("data:image/png;base64,")!important;
  background-size:750px 500px!important;
  background-repeat:no-repeat!important;
  background-position:center center!important;
}
.controller.xbox.disconnected div,.controller.custom.disconnected div{display:none!important}
.controller.xbox .quadrant,.controller.custom .quadrant,
.controller.xbox .meta,.controller.custom .meta{display:none!important}
/* Positions below are relative to the native 750 × 630 Xbox canvas. */
.controller.xbox .abxy,.controller.custom .abxy{position:absolute!important;left:491px!important;top:180px!important;width:150px!important;height:148px!important;background:none!important}
.controller.xbox .button,.controller.custom .button{position:absolute!important;width:47px!important;height:47px!important;border-radius:50%!important;background:none!important;opacity:0!important;margin:0!important;transform:none!important}
.controller.xbox .button.pressed,.controller.custom .button.pressed{opacity:1!important;background:radial-gradient(circle,rgba(255,255,255,.6),rgba(255,42,61,.36) 55%,transparent 76%)!important;box-shadow:0 0 11px #ff2938!important}
.controller.xbox .a,.controller.custom .a{left:50px!important;top:103px!important}
.controller.xbox .b,.controller.custom .b{left:100px!important;top:62px!important;right:auto!important}
.controller.xbox .x,.controller.custom .x{left:6px!important;top:62px!important}
.controller.xbox .y,.controller.custom .y{left:51px!important;top:16px!important}
.controller.xbox .arrows,.controller.custom .arrows{position:absolute!important;left:289px!important;top:249px!important;width:170px!important;height:38px!important;background:none!important}
.controller.xbox .back,.controller.xbox .start,.controller.custom .back,.controller.custom .start{position:absolute!important;width:34px!important;height:34px!important;border-radius:50%!important;background:none!important;opacity:0!important;float:none!important}
.controller.xbox .back,.controller.custom .back{left:0!important}
.controller.xbox .start,.controller.custom .start{left:125px!important;right:auto!important}
.controller.xbox .back.pressed,.controller.xbox .start.pressed,.controller.custom .back.pressed,.controller.custom .start.pressed{opacity:1!important;background:rgba(255,255,255,.48)!important;box-shadow:0 0 12px white!important}
.controller.xbox .sticks,.controller.custom .sticks{position:absolute!important;left:145px!important;top:222px!important;width:364px!important;height:190px!important;background:none!important}
.controller.xbox .stick,.controller.custom .stick{position:absolute!important;width:91px!important;height:91px!important;border-radius:50%!important;background-image:url("data:image/png;base64,")!important;background-repeat:no-repeat!important;background-size:750px 500px!important;box-shadow:0 0 5px #090909!important;opacity:1!important;will-change:margin-left,margin-top!important;transform:none!important}
.controller.xbox .stick.left,.controller.custom .stick.left{left:0!important;top:0!important;background-position:-145px -152px!important}
.controller.xbox .stick.right,.controller.custom .stick.right{left:276px!important;top:105px!important;background-position:-421px -257px!important}
.controller.xbox .stick.pressed,.controller.custom .stick.pressed{box-shadow:0 0 14px #ff2b3b!important}
.controller.xbox .dpad,.controller.custom .dpad{position:absolute!important;left:221px!important;top:307px!important;width:113px!important;height:113px!important;background:none!important}
.controller.xbox .face,.controller.custom .face{position:absolute!important;background:none!important;opacity:0!important;box-shadow:none!important}
.controller.xbox .face.pressed,.controller.custom .face.pressed{opacity:1!important;background:rgba(255,255,255,.37)!important;box-shadow:0 0 10px #fff!important}
.controller.xbox .face.up,.controller.custom .face.up{left:40px!important;top:0!important;width:33px!important;height:56px!important}
.controller.xbox .face.down,.controller.custom .face.down{left:40px!important;bottom:0!important;width:33px!important;height:56px!important}
.controller.xbox .face.left,.controller.custom .face.left{left:0!important;top:40px!important;width:56px!important;height:33px!important}
.controller.xbox .face.right,.controller.custom .face.right{right:0!important;top:40px!important;width:56px!important;height:33px!important}
.controller.xbox .bumpers,.controller.custom .bumpers{position:absolute!important;left:124px!important;top:145px!important;width:502px!important;height:30px!important;background:none!important}
.controller.xbox .bumper,.controller.custom .bumper{width:106px!important;height:25px!important;background:none!important;opacity:0!important;border-radius:40%!important}
.controller.xbox .bumper.left,.controller.custom .bumper.left{float:left!important}
.controller.xbox .bumper.right,.controller.custom .bumper.right{float:right!important}
.controller.xbox .bumper.pressed,.controller.custom .bumper.pressed{opacity:1!important;box-shadow:inset 0 8px 12px rgba(255,255,255,.65)!important}
.controller.xbox .triggers,.controller.custom .triggers{position:absolute!important;left:162px!important;top:67px!important;width:428px!important;height:105px!important;background:none!important}
.controller.xbox .trigger,.controller.custom .trigger{width:90px!important;height:95px!important;opacity:0;background:linear-gradient(to bottom,rgba(255,35,50,.12),rgba(255,30,47,.72))!important;border-radius:42% 42% 18% 18%!important}
.controller.xbox .trigger.left,.controller.custom .trigger.left{float:left!important}
.controller.xbox .trigger.right,.controller.custom .trigger.right{float:right!important}
.controller.xbox .trigger.pressed,.controller.custom .trigger.pressed{box-shadow:inset 0 0 18px #ff4654!important}

/* Separate moving caps: the base artwork contains only empty sockets. */
.controller.xbox .sticks,.controller.custom .sticks{left:145px!important;top:218px!important}
.controller.xbox .stick,.controller.custom .stick{width:91px!important;height:91px!important;background-size:91px 91px!important;background-position:center!important;border-radius:50%!important;transform:none!important;filter:none!important}
.controller.xbox .stick.left,.controller.custom .stick.left{left:0!important;top:0!important;background-image:url("data:image/png;base64,")!important;background-position:center!important}
.controller.xbox .stick.right,.controller.custom .stick.right{left:276px!important;top:102px!important;background-image:url("data:image/png;base64,")!important;background-position:center!important}
/* LB and RB occupy the narrow shoulders, not the trigger towers. */
.controller.xbox .bumpers,.controller.custom .bumpers{left:120px!important;top:139px!important;width:510px!important;height:37px!important}
.controller.xbox .bumper,.controller.custom .bumper{width:140px!important;height:32px!important;opacity:0!important;background:none!important;border-radius:45% 45% 15% 15%!important}
.controller.xbox .bumper.pressed,.controller.custom .bumper.pressed{opacity:1!important;background:linear-gradient(to bottom,rgba(255,255,255,.45),rgba(255,25,40,.28) 55%,transparent)!important;box-shadow:inset 0 6px 9px rgba(255,255,255,.4)!important}
/* Analog LT / RT intensity controls opacity in the GPV script. */
.controller.xbox .triggers,.controller.custom .triggers{left:149px!important;top:65px!important;width:452px!important;height:102px!important}
.controller.xbox .trigger,.controller.custom .trigger{width:103px!important;height:102px!important;opacity:0;background:linear-gradient(to bottom,rgba(255,36,54,.66),rgba(255,36,54,.05))!important;clip-path:polygon(24% 0%,75% 0%,96% 65%,100% 100%,0 100%,5% 65%)!important;box-shadow:none!important}
.controller.xbox .trigger.right,.controller.custom .trigger.right{transform:none!important;clip-path:polygon(25% 0%,76% 0%,95% 65%,100% 100%,0 100%,4% 65%)!important}

/* v6: black cavities stay fixed while only the caps translate with input. */
.controller.xbox .sticks:before,.controller.xbox .sticks:after,
.controller.custom .sticks:before,.controller.custom .sticks:after{
  content:"";position:absolute;display:block;width:82px;height:82px;
  border-radius:50%;background:#020203;z-index:0;
  box-shadow:inset 0 0 9px 4px #000;
}
.controller.xbox .sticks:before,.controller.custom .sticks:before{left:4.5px;top:4.5px}
.controller.xbox .sticks:after,.controller.custom .sticks:after{left:280.5px;top:106.5px}
.controller.xbox .stick,.controller.custom .stick{z-index:1!important}

/* The button circles measure 47px in the artwork. Keep light inside each rim. */
.controller.xbox .button.pressed,.controller.custom .button.pressed{
  background:radial-gradient(circle,rgba(255,255,255,.27) 0%,rgba(245,27,45,.36) 47%,transparent 72%)!important;
  box-shadow:inset 0 0 7px rgba(255,48,66,.75)!important;
}
.controller.xbox .stick.pressed,.controller.custom .stick.pressed{
  box-shadow:0 0 5px rgba(255,45,60,.7)!important;
}

/* Shoulder strips and upright triggers follow the art's separate outlines. */
.controller.xbox .bumpers,.controller.custom .bumpers{
  left:126px!important;top:142px!important;width:498px!important;height:26px!important;
}
.controller.xbox .bumper,.controller.custom .bumper{
  width:123px!important;height:22px!important;border-radius:70% 70% 20% 20%!important;
}
.controller.xbox .bumper.pressed,.controller.custom .bumper.pressed{
  background:linear-gradient(to bottom,rgba(255,255,255,.27),rgba(255,34,51,.2) 58%,transparent)!important;
  box-shadow:inset 0 5px 7px rgba(255,255,255,.25)!important;
}
.controller.xbox .triggers,.controller.custom .triggers{
  left:161px!important;top:66px!important;width:428px!important;height:76px!important;
}
.controller.xbox .trigger,.controller.custom .trigger{
  width:79px!important;height:74px!important;clip-path:none!important;
  border-radius:45% 48% 4% 4% / 35% 34% 4% 4%!important;
  background:linear-gradient(to bottom,rgba(244,35,52,.52),rgba(244,35,52,.31) 38%,transparent 95%)!important;
  box-shadow:none!important;
}
.controller.xbox .trigger.right,.controller.custom .trigger.right{
  clip-path:none!important;border-radius:48% 45% 4% 4% / 34% 35% 4% 4%!important;
}
